      x: { domain: [-5, 5], label: "X" },
      y: { domain: [-5, 5], label: "Y" },
      grid: true,
      marks: [
        Plot.dot(data, { x: "x", y: "y", fill: "red", opacity: 0.5, r: 3.5 }),
