      ]
    })}
  &lt;/div&gt;

  &lt;div&gt;
    &lt;h4 style="margin: 0 0 10px 0; text-align: center;"&gt;
      From deviations to sums of squares
    &lt;/h4&gt;

    ${Plot.plot({
      width: 380,
      height: 380,
      marginBottom: 45,
      marginTop: 35,
      marginLeft: 40,
      marginRight: 40,
      x: {
        domain: [-5, 5],
        label: "X"
      },
      y: {
        domain: [-5, 5],
        label: "Y"
      },
