      (${(100 * SSR / SST).toFixed(1)}% explained)&lt;br&gt;
      &lt;b&gt;SSE&lt;/b&gt; = ${SSE.toFixed(1)}
      (${(100 * SSE / SST).toFixed(1)}% unexplained)&lt;br&gt;
